						new ClassInfoRow("Negativni Voodoo - Kletba", "woodoo_curse", 40, "", "Kletba je soucasti skoly negativniho voodoo - umoznuje proklit nepritele a zpusobit mu tak velke nesnaze. Je k tomu treba jeho hlavu a dyku - efekt je dle pouziteho materialu dyky. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Negativni Voodoo - Oslabeni", "woodoo_curse", 40, "oslabenivoodoo", "Oslabeni je soucasti skoly negativniho voodoo - umoznuje oslabit odolnost monstra vuci zraneni chladem. Toto oslabeni se projevuje nejen na zraneni zpusobenem samanem, ale i ostatnimi postavami. Nelze ovsem oslabit monstrum zcela imunni na ledova kouzla. K provedeni teto schopnosti je treba drahokam - Rubin. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Negativni Voodoo - Koncentrace", "woodoo_curse", 40, "", "Koncentrace je soucasti skoly negativniho voodoo - umoznuje samanovi zasadit monstru zdrcujici uder kouzlem - tento uder je pak o 40% silnejsir. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Pozitivni voodoo - Boost", "woodoo", 30, "", "Boost je soucasti skoly pozitivniho voodoo - umoznuje samanovi posilovat (boostovat) sve spolubojovniky i sebe. Saman krome lehkeho lektvaru, ktery urcuje efekt, potrebuje i hlavu toho, koho chce posilit. Tuto schopnost je mozno 2x po deseti bodech vylepsit."),
						new ClassInfoRow("Pozitivni voodoo - Vitalita", "woodoo", 10, "voodoovit", "Vitalita je soucasti skoly pozitivniho voodoo - umoznuje samanovi docasne presunout 30 bodu z inteligence do vitality. K provedeni teto schopnosti je treba drahokam - Rubin. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Pozitivni voodoo - Inteligence", "woodoo", 10, "voodooint", "Inteligence je soucasti skoly pozitivniho voodoo - umoznuje samanovi docasne presunout 30 bodu z vitality do inteligence. K provedeni teto schopnosti je treba drahokam - Rubin. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Pozitivni voodoo - Rovnovaha", "woodoo", 10, "voodoorovnovaha", "Rovnovaha je soucasti skoly pozitivniho voodoo - umoznuje samanovi vratit sve staty do normalu. Tato schopnost zadne specialni body nevyzaduje."),
						new ClassInfoRow("Pozitivni voodoo - Obet", "woodoo_obet", 30, "voodooobet", "Voodoo obet je soucasti skoly pozitivniho voodoo - umoznuje samanovi presunout cast sve zivotni energie do magicke energie. Tuto schopnost je mozno 3x po deseti bodech vylepsit."),
						new ClassInfoRow("Voodoo pakty - pakt krve", "woodoo_pacts_boost", 20, "bloodpact", "Pakt krve je soucasti skoly voodoo pakty - umoznuje samanovi presunout cast zraneni svych spolubojovniku na sebe. Saman automaticky obdrzi zkusenosti, pokud je ziska spolubojovnik, s nimz je spojen. Tuto schopnost je mozno 2x po deseti bodech vylepsit."),
						new ClassInfoRow("Voodoo pakty - pakt zivota", "woodoo_lifepact", 30, "lifepact", "Pakt zivota je soucasti skoly voodoo pakty - umoznuje samanovi ulozit svoji (nebo spolubojovnikovu) dusi do schranky a za jeji pomoci se potom ozivit. Tuto schopnost je mozno 3x po deseti bodech vylepsit."),
						new ClassInfoRow("Voodoo pakty - pakt many", "pakty", 10, "manapact", "Pakt many je soucasti skoly voodoo pakty - umoznuje samanovi sobe nebo svym spolubojovnikum vyrazne zvysit regeneraci many. Tato schopnost zadne specialni body nevyzaduje."),
